        record["mailer_cost_usd"] * PATIENTS_PER_MEDICATION * FILLS_PER_YEAR_45_DAY
    )
    record["annual_mailer_cost_90_day_usd"] = (
        record["mailer_cost_usd"] * PATIENTS_PER_MEDICATION * FILLS_PER_YEAR_90_DAY
    )
    record["annual_payment_45_day_usd"] = (
        record["total_payment_per_fill_150_patients_usd"] * FILLS_PER_YEAR_45_DAY
    )
    record["annual_payment_90_day_usd"] = (
        record["total_payment_per_fill_150_patients_usd"] * FILLS_PER_YEAR_90_DAY
    )
    record["annual_margin_45_day_usd"] = (
        record["annual_payment_45_day_usd"]
        - record["annual_drug_cost_45_day_usd"]
        - record["annual_mailer_cost_45_day_usd"]
    )
    record["annual_margin_90_day_usd"] = (
        record["annual_payment_90_day_usd"]
        - record["annual_drug_cost_90_day_usd"]
        - record["annual_mailer_cost_90_day_usd"]
    )
    record["annual_margin_difference_90_minus_45_usd"] = (
        record["annual_margin_90_day_usd"] - record["annual_margin_45_day_usd"]
    )

    rounded = {}
    for key in MEDICATION_KEYS:
        if key in {"medication", "mailer_format"}:
            rounded[key] = record[key]
        else:
            rounded[key] = round_currency(record[key])
    return rounded


